package bodycodegen

import (
	"fmt"
	"go/ast"
	"go/types"
)

// Runtime length values retain Go's int type through inferred local reads.
// Other integer locals keep their established int64 projection, including its
// explicit annotations required to replay previously saved generated bytes.
func dependsOnRuntimeLength(expression ast.Expr, info *types.Info, lengths map[types.Object]bool) bool {
	found := false
	ast.Inspect(expression, func(node ast.Node) bool {
		if name, ok := node.(*ast.Ident); ok && lengths[info.Uses[name]] {
			found = true
		}
		if call, ok := node.(*ast.CallExpr); ok {
			if name, ok := call.Fun.(*ast.Ident); ok && name.Name == "len" {
				if _, builtin := info.Uses[name].(*types.Builtin); builtin {
					found = true
				}
			}
		}
		return !found
	})
	return found
}

func (e *integerBodyEvaluator) evaluateBodyPrimitive(call *ast.CallExpr) (any, bool, error) {
	name, ok := call.Fun.(*ast.Ident)
	if !ok || len(call.Args) != 1 {
		return nil, false, nil
	}
	object := e.information.Uses[name]
	_, builtin := object.(*types.Builtin)
	_, conversion := object.(*types.TypeName)
	if !(builtin && name.Name == "len") && !(conversion && name.Name == "int64") {
		return nil, false, nil
	}
	value, err := e.evaluateExpression(call.Args[0])
	if err != nil {
		return nil, true, err
	}
	if builtin {
		switch item := value.(type) {
		case string:
			value = int64(len(item))
		case *recordBodySequence:
			if item == nil {
				return nil, true, fmt.Errorf("len requires a present collection")
			}
			value = int64(len(item.Values))
		default:
			return nil, true, fmt.Errorf("len requires Text or a repeated field, got %T", value)
		}
	}
	value, err = coerceBodyValue(value, e.information.Types[call].Type)
	return value, true, err
}

func (e *integerBodyEvaluator) textOffset(expression ast.Expr, fallback int64) (int64, error) {
	if expression == nil {
		return fallback, nil
	}
	value, err := e.evaluateExpression(expression)
	if err != nil {
		return 0, err
	}
	offset, ok := value.(int64)
	if !ok {
		return 0, fmt.Errorf("Text byte offset requires an integer, got %T", value)
	}
	return offset, nil
}

func (e *integerBodyEvaluator) evaluateTextSlice(slice *ast.SliceExpr) (any, error) {
	if slice.Slice3 {
		return nil, fmt.Errorf("slices accept only low and high offsets")
	}
	value, err := e.evaluateExpression(slice.X)
	if err != nil {
		return nil, err
	}
	if sequence, ok := value.(*recordBodySequence); ok {
		if sequence == nil {
			return nil, fmt.Errorf("slice requires a present collection")
		}
		low, err := e.textOffset(slice.Low, 0)
		if err != nil {
			return nil, err
		}
		high, err := e.textOffset(slice.High, int64(len(sequence.Values)))
		if err != nil {
			return nil, err
		}
		if low < 0 || high < low || high > int64(len(sequence.Values)) {
			return nil, fmt.Errorf("collection slice [%d:%d] exceeds length %d", low, high, len(sequence.Values))
		}
		return &recordBodySequence{Kind: sequence.Kind, Values: sequence.Values[low:high]}, nil
	}
	text, ok := value.(string)
	if !ok {
		return nil, fmt.Errorf("slice requires Text or an ordered collection, got %T", value)
	}
	low, err := e.textOffset(slice.Low, 0)
	if err != nil {
		return nil, err
	}
	high, err := e.textOffset(slice.High, int64(len(text)))
	if err != nil {
		return nil, err
	}
	if low < 0 || high < low || high > int64(len(text)) {
		return nil, fmt.Errorf("Text slice byte offsets [%d:%d] exceed length %d", low, high, len(text))
	}
	return text[low:high], nil
}
